   487  void CoapBase::Receive(ot::Message &aMessage, const Ip6::MessageInfo &aMessageInfo)
   488  {
   489      Message &message = static_cast<Message &>(aMessage);
   490
   491      if (message.ParseHeader() != OT_ERROR_NONE)
   492      {
   493          otLogDebgCoap("Failed to parse CoAP header");
   494      }
   495      else if (message.IsRequest())
   496      {
   497          ProcessReceivedRequest(message, aMessageInfo);
   498      }
   499      else
   500      {
   501          ProcessReceivedResponse(message, aMessageInfo);
   502      }
